import{newSpecPage}from"@stencil/core/testing";import{ScSubscription}from"../sc-subscription";const renderActions=async e=>{const t=await newSpecPage({components:[ScSubscription],html:"<sc-subscription></sc-subscription>"});return t.root.subscription={can_modify:!0,...e},await t.waitForChanges(),t.root.shadowRoot.textContent},scheduledPause={status:"active",cancel_at_period_end:1786e6,current_period_end_at:1786e6,current_period_end_at_date:"March 1, 2026",restore_at:1817e6,restore_at_date:"June 1, 2026"};describe("sc-subscription",(()=>{it("offers Don't Pause for a scheduled pause",(async()=>{const e=await renderActions(scheduledPause);expect(e).toContain("Don't Pause"),expect(e).not.toContain("Restore Plan")})),it("offers Restore Plan for a scheduled cancellation",(async()=>{const e=await renderActions({...scheduledPause,restore_at:null,restore_at_date:null});expect(e).toContain("Restore Plan"),expect(e).not.toContain("Don't Pause")}))}));